 "partner.s0.h": {"it": "Comune e Pro Loco di San Raffaele Cimena.", "en": "The Municipality and Pro Loco of San Raffaele Cimena."},
 "partner.s0.p0": {"it": "Il Comune di San Raffaele Cimena è partner strategico dell’organizzazione; la Pro Loco porta il suo radicamento nel paese.", "en": "The Municipality of San Raffaele Cimena is a strategic partner in the organisation; the Pro Loco brings its roots in the village."},
 "alt.Ilum-collettivo_MoonFestival_5ed_piazza-notte": {"it": "La piazza del borgo di notte, con un tripode da circo e il pubblico intorno.", "en": "The village square at night, with a circus tripod and the audience around it."},
 "credito.Ilum-collettivo_MoonFestival_5ed_piazza-notte": {"it": "© Ilum collettivo · Moon Festival, 5ª edizione", "en": "© Ilum collettivo · Moon Festival, 5th edition"},
