 "area-stampa.sm.0": {"it": "Comunicati", "en": "Press releases"},
 "area-stampa.sm.1": {"it": "Foto e loghi", "en": "Photos and logos"},
 "area-stampa.sm.2": {"it": "Contatti", "en": "Contact"},
 "area-stampa.l0.p0": {"it": "[DA FORNIRE: comunicati stampa]", "en": "[TO BE PROVIDED: press releases]"},
 "area-stampa.l0.h": {"it": "Comunicati", "en": "Press releases"},
 "area-stampa.l1.p0": {"it": "[DA FORNIRE: cartella foto in alta risoluzione con crediti, loghi]", "en": "[TO BE PROVIDED: high-resolution photo folder with credits, logos]"},
 "area-stampa.l1.h": {"it": "Foto e loghi", "en": "Photos and logos"},
 "area-stampa.l2.p0": {"it": "Scrivici a info@associazionednart.it con oggetto «Stampa Moon Festival». [REFERENTE UFFICIO STAMPA]", "en": "Write to us at info@associazionednart.it with the subject “Stampa Moon Festival” (Press Moon Festival). [PRESS OFFICE CONTACT]"},
