 "area.partecipa": {"it": "Partecipa", "en": "Take part"},
 "partecipa.h1": {"it": "Anche tu fai il Moon.", "en": "You make Moon too."},
 "partecipa.lead": {"it": "Si partecipa in tanti modi: proponendo, costruendo, ospitando, camminando. O semplicemente venendo.", "en": "There are many ways to take part: proposing, building, hosting, walking. Or simply coming."},
 "part.tile.moon-lab": {"it": "Moon Lab", "en": "Moon Lab"},
 "part.tile.moon-lab.f": {"it": "Una residenza gratuita per costruire il festival, dal 27 agosto al 7 settembre 2027.", "en": "A free residency to build the festival, from 27 August to 7 September 2027."},
 "part.tile.call": {"it": "Call artist*", "en": "Open call for artists"},
 "part.tile.call.f": {"it": "Cerchiamo proposte capaci di incontrare davvero il borgo.", "en": "We are looking for proposals that can truly meet the village."},
 "part.tile.installazioni": {"it": "Installazioni", "en": "Installations"},
 "part.tile.installazioni.f": {"it": "Opere già nate, nuovi luoghi da abitare.", "en": "Works already made, new places to inhabit."},
 "part.tile.lab": {"it": "Proponi un laboratorio", "en": "Propose a workshop"},
 "part.tile.lab.f": {"it": "Hai un laboratorio da condividere? Raccontaci cosa vorresti costruire.", "en": "Do you have a workshop to share? Tell us what you would like to build."},
 "part.tile.cantina": {"it": "Apri la tua cantina", "en": "Open your cellar"},
 "part.tile.cantina.f": {"it": "Quello che non usi può diventare un mondo.", "en": "What you no longer use can become a world."},
 "part.tile.adotta": {"it": "Adotta un artista", "en": "Host an artist"},
 "part.tile.adotta.f": {"it": "Una stanza libera. Un incontro in più.", "en": "A spare room. One more encounter."},
 "part.tile.walk": {"it": "Moon Walk", "en": "Moon Walk"},
 "part.tile.walk.f": {"it": "Camminate collettive fino al festival.", "en": "Group walks to the festival."},
 "part.tile.laboratori": {"it": "Partecipare ai laboratori", "en": "Join the workshops"},
 "part.tile.laboratori.f": {"it": "Non serve saper fare tutto. A volte basta cominciare.", "en": "You don’t need to know how to do everything. Sometimes starting is enough."},
 "part.tile.registrazione": {"it": "Registrazione al festival", "en": "Festival registration"},
 "part.tile.registrazione.f": {"it": "L’ingresso è libero. Registrarti ci aiuta ad accoglierti meglio.", "en": "Entry is free. Registering helps us welcome you better."},
