 "area.call-artisti": {"it": "Spettacoli", "en": "Performances"},
 "call-artisti.h1": {"it": "Call artist* 2027", "en": "Open call for artists 2027"},
 "call-artisti.lead": {"it": "Cerchiamo spettacoli capaci di incontrare davvero il borgo: teatro, circo, danza, musica, teatro di figura, performance.", "en": "We are looking for performances that can truly meet the village: theatre, circus, dance, music, puppetry, performance."},
 "call.sm.0": {"it": "Spettacoli", "en": "Performances"},
 "call.sm.1": {"it": "Installazioni", "en": "Installations"},
 "call.sm.2": {"it": "Laboratori", "en": "Workshops"},
 "call.sm.3": {"it": "Moon Lab", "en": "Moon Lab"},
 "call.sm.4": {"it": "Volontar* del festival", "en": "Festival volunteers"},
 "call.sm.5": {"it": "Apri la tua cantina", "en": "Open your cellar"},
 "call.sm.6": {"it": "Adotta un artista", "en": "Host an artist"},
 "call.info.occ": {"it": "In breve", "en": "At a glance"},
 "call.info.h2": {"it": "Cosa c’è da sapere", "en": "What to know"},
