 "sost.sm.0": {"it": "Perché sostenerlo", "en": "Why support it"},
 "sost.perche.h2": {"it": "Cultura che si fa insieme.", "en": "Culture made together."},
 "sost.perche.t": {"it": "Il Moon non vende niente. È un progetto culturale partecipativo che lavora su quattro cose: cultura accessibile, partecipazione giovane, sostenibilità e territorio.", "en": "Moon doesn’t sell anything. It is a participatory cultural project that works on four things: accessible culture, youth participation, sustainability and the local area."},
 "sost.imp.o": {"it": "Per imprese e realtà del territorio", "en": "For businesses and local organisations"},
 "sost.imp.h2": {"it": "Facciamo il Moon con te.", "en": "Let’s make Moon with you."},
 "sost.imp.t": {"it": "Cerchiamo partnership, sponsorizzazioni tecniche e collaborazioni. Raccontaci la tua idea: ti rispondiamo noi.", "en": "We are looking for partnerships, in-kind sponsorship and collaborations. Tell us your idea and we will get back to you."},
