 "area.moon-walk": {"it": "Moon Walk", "en": "Moon Walk"},
 "moon-walk.h1": {"it": "Moon Walk 2027", "en": "Moon Walk 2027"},
 "moon-walk.lead": {"it": "Il viaggio fa parte del festival: camminate collettive che attraversano il paesaggio e accompagnano le persone fino al borgo.", "en": "The journey is part of the festival: group walks across the landscape that bring people all the way to the village."},
 "titolo.moon-walk": {"it": "Moon Walk 2027 · Moon Festival", "en": "Moon Walk 2027 · Moon Festival"},
 "area.registrazione": {"it": "Registrazione", "en": "Registration"},
 "registrazione.h1": {"it": "Registrazione al festival", "en": "Festival registration"},
 "registrazione.lead": {"it": "Il Moon Festival è gratuito. Registrarti non è obbligatorio, ma ci aiuta a prepararci ad accoglierti.", "en": "Moon Festival is free. Registering is not compulsory, but it helps us get ready to welcome you."},
 "titolo.registrazione": {"it": "Registrazione al festival · Moon Festival", "en": "Festival registration · Moon Festival"},
 "area.iscrizione-laboratori": {"it": "Partecipa ai laboratori", "en": "Join the workshops"},
